    /// <summary>Stores the epoch that holds when this link was observed, allowing subsequent observations of the same producer to realize that there's an existing link, avoiding the creation of a new, redundant link. A value of <c>null</c> indicates that the link cannot be assumed to be valid based on the epoch counter.</summary>
    [JsName("knownValidAtEpoch")]
    public object? KnownValidAtEpoch { get; set; }
    [JsName("lastReadVersion")]
    public double LastReadVersion { get; set; }
    [JsName("prevConsumer")]
    public ReactiveLink? PrevConsumer { get; set; }
    [JsName("nextConsumer")]
    public ReactiveLink? NextConsumer { get; set; }
    [JsName("nextProducer")]
    public ReactiveLink? NextProducer { get; set; }
}

