/// <summary>A set of flags to be used with Queries. NOTE: Ensure changes here are reflected in <c>packages/compiler/src/render3/view/compiler.ts</c></summary>
/// <remarks>Declared here with the library's own values, so it needs no import.</remarks>
public enum QueryFlags
{
    /// <summary>No flags</summary>
    none = 0,

    /// <summary>Whether or not the query should descend into children.</summary>
    descendants = 1,

    /// <summary>The query can be computed statically and hence can be assigned eagerly. NOTE: Backwards compatibility with ViewEngine.</summary>
    isStatic = 2,

    /// <summary>If the <c>QueryList</c> should fire change event only if actual change to query was computed (vs old behavior where the change was fired whenever the query was recomputed, even if the recomputed query resulted in the same list.)</summary>
    emitDistinctChangesOnly = 4,
}
